/* @author MILO-GAO(高振銘)@2020 */ package page2020.core;import java.util.ArrayList;import java.util.LinkedHashMap;import java.util.List;import java.util.Set;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.util.EmptyUtil;public class Prop<T, C> extends Name<T> {	private static Logger log = LoggerFactory.getLogger(Prop.class);	private LinkedHashMap<String, C> data = new LinkedHashMap<String, C>();	public Set<String> keys() {		return this.data.keySet();	}	public boolean hasKey(String key) {		return this.data.containsKey(key);	}	public String key(int index) {		return this.isRange(index) ? (String) this.data.keySet().toArray()[index] : null;	}	public int key(String name) {		int index = -1;		for (String key : this.data.keySet()) {			index += 1;			if (key.equals(name)) {				return index;			}		}		return index;	}	public List<C> values() {		List<C> list = new ArrayList<C>();		if (EmptyUtil.not(this.data)) {			this.data.forEach((key, value) -> list.add(value));		}		return list;	}	public C value(String key) {		return this.data.get(key);	}	public C value(int index) {		return this.isRange(index) ? this.values().get(index) : null;	}	public T add(String key, C value) {		try {			this.data.put(key, value);			return super.bean();		} catch (Exception ex) {			log.error("add: " + ex.toString());		}		return null;	}	public C set(int index, C value) {		if (this.isRange(index)) {			String key = (String) this.keys().toArray()[index];			C old = this.data.put(key, value);			return old;		}		return null;	}	public C remove(String key) {		return this.data.remove(key);	}	public C remove(int index) {		if (this.isRange(index)) {			String key = (String) this.keys().toArray()[index];			return this.data.remove(key);		}		return null;	}	public T merge(Prop<T, C> item) {		if (item.count() > 0) {			item.getData().forEach((key, value) -> this.data.put(key, value));		}		return super.bean();	}	public int count() {		return this.data.size();	}	private boolean isRange(int index) {		return (index >= 0 && index < this.data.size()) ? true : false;	}	public LinkedHashMap<String, C> getData() {		return data;	}	public void setData(LinkedHashMap<String, C> data) {		this.data = data;	}	}